// Generate js/data/ja-strokes.js — the stroke paths of every kana, from KanjiVG
// (https://kanjivg.tagaini.net, © Ulrich Apel, CC BY-SA 3.0; docs/japanese-plan.md §4.3).
// The SVGs are fetched once into tools/.cache/kanjivg/ (git-ignored) and the generated file is
// committed with the attribution, never hand-edited (the ShareAlike boundary: only this data file
// carries the licence).
//
//   node tools/gen_ja_strokes.mjs           fetch what is missing, then write
//   node tools/gen_ja_strokes.mjs --check   fail if the committed file differs from the cache
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const CACHE = path.join(ROOT, "tools", ".cache", "kanjivg");
const OUT = path.join(ROOT, "js", "data", "ja-strokes.js");
const SRC = "https://raw.githubusercontent.com/KanjiVG/kanjivg/master/kanji/";
const CHECK = process.argv.includes("--check");

// the kana inventory: every hiragana and katakana a learner writes, small kana included
const chars = [];
for (let c = 0x3041; c <= 0x3093; c++) chars.push(String.fromCharCode(c));       // ぁ … ん
for (let c = 0x30a1; c <= 0x30f4; c++) chars.push(String.fromCharCode(c));       // ァ … ヴ
chars.push("ー");
const hex = ch => ch.codePointAt(0).toString(16).padStart(5, "0");

fs.mkdirSync(CACHE, { recursive: true });
const missing = [];
for (const ch of chars) {
  const f = path.join(CACHE, hex(ch) + ".svg");
  if (fs.existsSync(f)) continue;
  if (CHECK) { missing.push(ch); continue; }
  const r = await fetch(SRC + hex(ch) + ".svg");
  if (r.status === 404) { missing.push(ch); continue; }
  if (!r.ok) throw new Error(ch + " → HTTP " + r.status);
  fs.writeFileSync(f, await r.text());
}

const data = {};
for (const ch of chars) {
  const f = path.join(CACHE, hex(ch) + ".svg");
  if (!fs.existsSync(f)) continue;
  const svg = fs.readFileSync(f, "utf8");
  // stroke paths in document order (KanjiVG numbers them -s1, -s2 … in writing order)
  const paths = [...svg.matchAll(/<path\b[^>]*\bid="kvg:[0-9a-f]+-s(\d+)"[^>]*\bd="([^"]+)"/g)]
    .map(m => [+m[1], m[2]]).sort((a, b) => a[0] - b[0]).map(m => m[1]);
  if (paths.length) data[ch] = paths;
}

const text = `/* Stroke paths for every kana, from KanjiVG (https://kanjivg.tagaini.net), © Ulrich Apel,
   CC BY-SA 3.0. GENERATED by tools/gen_ja_strokes.mjs — never hand-edited (docs/japanese-plan.md
   §4.3, the ShareAlike boundary). KOS.jaStrokes[char] = [path d, …] in writing order. */
(function (G) { (G.KOS = G.KOS || {}).jaStrokes = ${JSON.stringify(data)}; })(typeof window !== "undefined" ? window : globalThis);
`;
if (CHECK) {
  const same = fs.existsSync(OUT) && fs.readFileSync(OUT, "utf8") === text;
  console.log(same ? "✓ ja-strokes.js matches KanjiVG (" + Object.keys(data).length + " kana)" : "✗ ja-strokes.js differs from the cache — run node tools/gen_ja_strokes.mjs");
  process.exit(same ? 0 : 1);
}
fs.writeFileSync(OUT, text);
console.log("wrote " + path.relative(ROOT, OUT) + ": " + Object.keys(data).length + " of " + chars.length + " kana" + (missing.length ? " (KanjiVG has no file for " + missing.join(" ") + ")" : ""));
